import Foundation

/// Resolves the selected file before AppDelegate performs any presentation.
/// File inspection is shared with normal reopening; Finder itself is never
/// needed to evaluate a selection result.
enum FinderReopenDecision: Equatable {
    case open(URL)
    case warning(title: String, message: String, settingsURL: String?)
}

enum FinderReopenLogic {
    static func resolve(_ result: Result<FinderSelectionService.Selection, Error>) -> FinderReopenDecision {
        switch result {
        case .success(let selection): return resolve(selection)
        case .failure(let error): return resolve(error)
        }
    }

    private static func resolve(_ selection: FinderSelectionService.Selection) -> FinderReopenDecision {
        switch selection {
        case .none:
            return .warning(title: "No Finder Selection", message: "Select an image file in Finder, then press the shortcut again.", settingsURL: nil)
        case .multiple(let count):
            return .warning(title: "Multiple Finder Items Selected", message: "Select exactly 1 image file in Finder (you selected \(count)), then press the shortcut again.", settingsURL: nil)
        case .single(let url):
            return inspect(url)
        }
    }

    private static func inspect(_ url: URL) -> FinderReopenDecision {
        switch ImageSafety.inspectFile(at: url) {
        case .tooLarge:
            return .warning(title: "Image is too large", message: "This image is too large to open safely. Choose a smaller screenshot and try again.", settingsURL: nil)
        case .notAnImage:
            return .warning(title: "Not an Image", message: "The selected Finder item is not a readable image.", settingsURL: nil)
        case .safe:
            return .open(url)
        }
    }

    private static func resolve(_ error: Error) -> FinderReopenDecision {
        let error = error as NSError
        guard error.domain == "FinderSelectionService" else {
            return .warning(title: "Finder Error", message: error.localizedDescription, settingsURL: nil)
        }
        switch error.code {
        case -2:
            return .warning(title: "Automation Permission Required",
                message: "Zoomies needs permission to communicate with Finder.\n\nOpen System Settings → Privacy & Security → Automation, and enable Finder under Zoomies.",
                settingsURL: "x-apple.systempreferences:com.apple.preference.security?Privacy_Automation")
        case -3:
            return .warning(title: "Finder didn’t respond", message: error.localizedDescription, settingsURL: nil)
        default:
            return .warning(title: "Finder Error", message: error.localizedDescription, settingsURL: nil)
        }
    }
}

// MARK: - Finish

@available(macOS 15, *)
private func runFinish(sessionID id: UUID?) async {
    guard let id, !isStale(sessionID: id) else { return }
    await finalizeSession(sessionID: id, publish: true)
}

/// Stops capture, waits for recording-output finalization (bounded),
/// then publishes the MP4 and returns to idle. Same path for manual
/// stop, automatic stop, stop-during-startup, and shutdown.
@available(macOS 15, *)
private func finalizeSession(sessionID id: UUID, publish: Bool) async {
    guard let session, session.id == id, !isStale(sessionID: id) else {
        goIdleIfCurrent(sessionID: id)
        return
    }
    guard !session.finalizationStarted else { return }
    session.finalizationStarted = true
    do {
        try await session.stream.stopCapture()
    } catch {
        // Continue: the recording-output delegate still reports
        // finalization, or the timeout below bounds the wait.
    }
    await waitForFinalize(session: session)
    var savedURL: URL?
    if publish {
        savedURL = publishSession(session)
    } else {
        try? FileManager.default.removeItem(at: session.tempURL)
    }
    if sessionBox as? ScreenRecordingSession === session {
        sessionBox = nil
    }
    // Report synchronously on the main actor right after going idle, so no
    // other operation can start between saving and showing the panel.
    let shouldReport = savedURL != nil && !isTerminating
    isTerminating = false
    goIdleIfCurrent(sessionID: id)
    if shouldReport, let savedURL {
        onRecordingSaved?(savedURL)
    }
}

@available(macOS 15, *)
private func waitForFinalize(session: ScreenRecordingSession) async {
    if session.finalized {
        return
    }
    await withCheckedContinuation { (continuation: CheckedContinuation<Void, Never>) in
        session.finalizeContinuation = continuation
        let id = session.id
        Task {
            try? await Task.sleep(for: .seconds(self.finalizationDelay))
            await MainActor.run {
                self.timeoutFinalize(sessionID: id)
            }
        }
    }
}

private func timeoutFinalize(sessionID id: UUID) {
    if #available(macOS 15, *) {
        guard let session, session.id == id, !session.finalized else { return }
        session.finalized = true
        session.finalizeContinuation?.resume()
        session.finalizeContinuation = nil
    }
}

/// Moves a finalized recording to the Desktop and returns its final URL.
/// Returns nil unless the recording-output delegate confirmed successful
/// finalization: a nonempty temp file or a finalize timeout alone is not
/// proof of success.
@available(macOS 15, *)
@discardableResult
private func publishSession(_ session: ScreenRecordingSession) -> URL? {
    guard session.didFinishRecording else {
        try? FileManager.default.removeItem(at: session.tempURL)
        errorPresenter(
            "Recording failed",
            "The recording couldn’t be finalized, so it wasn’t saved."
        )
        return nil
    }
    let fileManager = FileManager.default
    guard fileManager.fileExists(atPath: session.tempURL.path),
          let size = try? fileManager.attributesOfItem(atPath: session.tempURL.path)[.size] as? NSNumber,
          size.intValue > 0 else {
        try? FileManager.default.removeItem(at: session.tempURL)
        return nil
    }
    do {
        let desktop = recordingDirectory
        try fileManager.createDirectory(at: desktop, withIntermediateDirectories: true)
        let baseName = Self.recordingBaseName(date: Date())
        let target = UniqueFileURLLogic.uniqueURL(forProposedName: baseName + ".mp4",
                                                  in: desktop,
                                                  fileExists: { fileManager.fileExists(atPath: $0) })
        try fileManager.moveItem(at: session.tempURL, to: target)
        return target
    } catch {
        // A finalized recording is the user's only copy until the move
        // succeeds. Keep it available for recovery if the destination fails.
        errorPresenter("Couldn’t save recording",
                       "\(error.localizedDescription)\n\nThe recording was kept at \(session.tempURL.path).")
        return nil
    }
}

private func fail(sessionID id: UUID, error: Error) {
    guard !isStale(sessionID: id) else { return }
    isTerminating = false
    stopPollTimer()
    if #available(macOS 15, *) {
        if let session, session.id == id {
            try? FileManager.default.removeItem(at: session.tempURL)
        }
        if session?.id == id {
            sessionBox = nil
        }
    }
    goIdleIfCurrent(sessionID: id)
    errorPresenter("Recording failed", (error as NSError).localizedDescription)
}

private func goIdleIfCurrent(sessionID id: UUID) {
    guard !isStale(sessionID: id) else { return }
    Self.logger.notice("Recording returned to idle")

        DispatchQueue.main.async { [weak self] in
            self?.captureArea()
        }
        return
    }

    guard canStartAreaCapture() else {
        return
    }

    performCapture { [self] in
        guard let image = try await areaCapture() else { return nil }
        guard let screen = await MainActor.run(body: { self.captureScreen(.area) }) else { return nil }
        return (image, screen.displayID)
    }
}

/// Captures the full contents of the display under the mouse.
func captureFullScreen() {
    if !Thread.isMainThread {
        DispatchQueue.main.async { [weak self] in
            self?.captureFullScreen()
        }
        return
    }

    guard canStartFullScreenCapture() else {
        return
    }
    guard let screen = captureScreen(.fullScreen) else {
        return
    }

    captureRegion(in: screen.frame, on: screen)
}

/// Starts the rename/note flow for an already-saved image.
func beginPostCaptureFlow(forExistingFileAt url: URL, on screen: NSScreen? = nil, escapeKeyDeletesFile: Bool = true) {
    beginPostCaptureFlow(forExistingFileAt: url,
                         initialImage: nil,
                         initialFilePersistence: nil,
                         initialScreenshotCounter: nil,
                         on: screen,
                         escapeKeyDeletesFile: escapeKeyDeletesFile)
}

func beginPostCaptureFlow(forExistingFileAt url: URL,
                          initialImage: NSImage? = nil,
                          initialFilePersistence: Task<URL, Error>? = nil,
                          initialScreenshotCounter: Int? = nil,
                          on screen: NSScreen? = nil,
                          escapeKeyDeletesFile: Bool = true) {
    if !Thread.isMainThread {
        DispatchQueue.main.async { [weak self] in
            self?.beginPostCaptureFlow(forExistingFileAt: url,
                                       initialImage: initialImage,
                                       initialFilePersistence: initialFilePersistence,
                                       initialScreenshotCounter: initialScreenshotCounter,
                                       on: screen,
                                       escapeKeyDeletesFile: escapeKeyDeletesFile)
        }
        return
    }

    guard activeWorkflow == nil else { return }

    if initialImage == nil {
        switch ImageSafety.inspectFile(at: url) {
        case .tooLarge:
            presentError(
                title: "Image is too large",
                message: "This image is too large to open safely."
            )
            return
        case .notAnImage, .safe:
            break
        }
    }

    let workflow = ScreenshotWorkflowController(
        fileURL: url,
        initialImage: initialImage,
        initialFilePersistence: initialFilePersistence,
        initialScreenshotCounter: initialScreenshotCounter,
        settingsStore: settingsStore,
        clipboardService: clipboardService,
        backupService: backupService,
        sourceScreen: screen,
        escapeKeyDeletesFile: escapeKeyDeletesFile
    )

    workflow.onFinish = { [weak self] in
        self?.activeWorkflow = nil
    }

    activeWorkflow = workflow
    workflowPresenter(workflow)
}

var isBusyForUserCommands: Bool {
    isCaptureInProgress || activeWorkflow != nil
}

/// Saves an arbitrary image to the Desktop using the current settings
/// (maxWidth, filename template) and returns the resulting URL.
func saveImageToDesktop(_ image: NSImage) throws -> URL {
    let prepared = try prepareCaptureSave(for: image)
    return try persistPreparedCapture(prepared)
}

// MARK: - Capture pipeline

private func canStartNewCapture() -> Bool {
    if isCaptureInProgress {
        return false
    }
    if activeWorkflow != nil {
        return false
    }
    return true
}

func canStartAreaCapture() -> Bool {
    return canStartNewCapture()
}

func canStartFullScreenCapture() -> Bool {
    canStartNewCapture()
}

private func captureRegion(in rect: CGRect, on screen: ScreenSnapshot) {
    performCapture { [self] in
        let image: CGImage
        if let regionCapture {
            image = try await regionCapture(rect, screen)
        } else {
            image = try await captureCGImage(rect: rect, on: screen)
        }
        return (image, screen.displayID)
    }
}

/// Both capture adapters share command gating, cancellation, failure and
/// the handoff to persistence. A nil result is user cancellation.
private func performCapture(_ operation: @escaping () async throws -> (CGImage, CGDirectDisplayID)?) {
    guard canStartNewCapture() else { return }
    isCaptureInProgress = true
    Task { [self] in
        do {
            let result = try await operation()
            try await MainActor.run {
                defer { self.isCaptureInProgress = false }
                guard let (image, displayID) = result else { return }
                try self.finishCapture(with: image, onDisplayID: displayID)
            }
        } catch {
            await MainActor.run {
                self.isCaptureInProgress = false
                self.handleCaptureFailure(error)
            }
        }
    }
}

private func finishCapture(with cgImage: CGImage, onDisplayID displayID: CGDirectDisplayID) throws {
    let imageSize = NSSize(width: CGFloat(cgImage.width), height: CGFloat(cgImage.height))
    let image = NSImage(cgImage: cgImage, size: imageSize)
    let preparedSave = try prepareCaptureSave(for: image)
    let initialFilePersistence = makeInitialFilePersistenceTask(for: preparedSave)
    beginPostCaptureFlow(forExistingFileAt: preparedSave.targetURL,

