        ?? menuBarScreen
        ?? NSScreen.main ?? NSScreen.screens.first
    guard let screen, let displayID = screen.displayID else { return nil }
    return ScreenSnapshot(displayID: displayID, frame: screen.frame, scale: screen.backingScaleFactor)
}

